1	import { theme } from '../../theme';
2	import { MAX_STEPS, cueFrame, stepAt, stepSpans } from '../cues';
3	import { OnFrame } from '../Film';
4	import { glassRoom, linesRoom } from '../lens';
5	import { Mark } from '../marks';
6	import { FACE, emOf } from '../measure';
7	import { frameBox, stripOf } from '../strip';
8	import { BREAKS, LIMITS, boxRoom, clampEnd, clampWidth, decisive, fitText, type Decisive } from '../text';
9	import { GlassBlock, Lines, ROLES, Type, fitRef, fitRoles, heightOf, ringOf, useScene, widthOf, type Room, type SceneOf, type SceneParts } from '../ui';
10	
11	const { color, size, leading, space, film, loupe, motion } = theme;
12	
13	const COMMAND_LINES = 2;
14	// A cross takes this share of the frame it rejects; a ring stands this far off the result it selects, in em.
15	const CROSS = { width: 1.04, height: 0.74 };
16	const RING = { x: 0.34, y: 0.42, min: 30 };
17	const RING_RIM = 36;   // extra margin a result keeps from the rim of the glass, so its ring stays on the glass
18	// Under the glass the cross is struck through the result alone: this much wider and taller than it.
19	const STRUCK = { width: 1.3, height: 2.3 };
20	const GAP = space.xxl + space.xs;   // between the command and the result under the glass: room for the ring to pass
21	
22	/** The steps of the scene with what each comes down to, and when its mark is drawn. */
23	function useSteps(scene: SceneOf<'terminal'>) {
24	  const m = useScene();
25	  const steps = scene.steps.slice(0, MAX_STEPS);
26	  const spans = stepSpans(steps.map((s) => s.entryId), scene.lines, m.lines, m.duration);
27	  const advance = motion.stepSec * m.fps;
28	  return {
29	    m,
30	    position: stepAt(scene, m.lines, m.frame, m.duration, m.fps, m.settled),
31	    steps: steps.map((step, i) => ({
32	      ok: step.ok,
33	      command: `$ ${step.command.replace(/\s+/g, ' ').trim()}`,
34	      result: decisive(clampEnd(step.output, LIMITS.output), step.ok),
35	      entryId: step.entryId,
36	      // The pencil waits for the lens: after the landing for the first step, after the strip has moved on for the others.
37	      cue: cueFrame(spans[i]!, m.fps, i === 0 ? m.landing : spans[i]!.start + advance),
38	    })),
39	  };
40	}
41	
42	/** The decisive part of a step's output, fitted: a count in display, a line of output in code. */
43	const fitResult = (result: Decisive, room: Room) =>
44	  result.kind === 'line' ? fitRoles(result.headline, ROLES.output, room, { maxLines: 3, soft: BREAKS.name }) : fitRoles(result.headline, ROLES.result, room, { maxLines: 2, fewest: true });
45	
46	/** How far a ring stands off a result set at `size` px. */
47	const ringPad = (size: number) => ({ x: Math.max(RING.min, RING.x * size), y: Math.max(RING.min, RING.y * size) });
48	
49	export const Terminal: SceneParts<'terminal'> = {
50	  Film: ({ scene }) => {
51	    const { m, steps, position } = useSteps(scene);
52	    const strip = stripOf(m.shot.unit, m.shot.half);
53	    const box = frameBox(strip, m.shot.at, 0);
54	    const pad = m.shot.unit * film.padding;
55	    // The skirt of the lens lies over the far end of the step before the one it rests on. Every step is set to
56	    // the width that stays clear there, so its text holds still when the strip moves it on.
57	    const width = Math.min(box.width - 2 * pad, -loupe.skirt.outer * m.shot.lens.scale - frameBox(strip, m.shot.at, -1).left - pad - space.xxl);
58	    const row = size.code.ref * leading.code;
59	    const detail = size.text.detail * leading.text;
60	    return (
61	      <>
62	        {steps.map((step, i) => {
63	          const room = box.height - 2 * pad - 2 * row - space.md - (step.result.detail ? detail : 0);
64	          const head = fitResult(step.result, boxRoom(width, room));
65	          const drawn = m.drawn(step.cue);
66	          // Type under a cross keeps a halo, so the pencil passes behind it.
67	          const halo = step.ok ? undefined : color.film.frame;
68	          return (
69	            // A step still to come stays dark until the strip brings it under the lens.
70	            <OnFrame key={i} k={i} style={{ opacity: i <= position + 0.5 ? 1 : 0 }}>
71	              {step.ok ? null : <Mark kind="cross" x={pad + width / 2} y={box.height / 2} width={width * CROSS.width} height={box.height * CROSS.height} seed={i + 3} progress={drawn} />}
72	              <div style={{ position: 'absolute', left: pad, top: pad, width }}>
73	                <Type face={FACE.code} size={size.code.ref} leading={leading.code} tone={color.muted} halo={halo} style={{ marginBottom: space.md }}>{clampWidth(step.command, width / size.code.ref, emOf(FACE.code))}</Type>
74	                <div style={{ position: 'relative', width: 'fit-content' }}>
75	                  <Lines fitted={head} face={head.role.face} leading={head.role.type.leading} halo={halo} />
76	                  {step.ok ? <Mark kind="ring" x={widthOf(head, head.role.face) / 2} y={heightOf(head) / 2} {...ringOf(head, head.role.face, head.role.type.leading, ringPad(head.size))} seed={i + 11} progress={drawn} /> : null}
77	                </div>
78	                {step.result.detail ? <Type face={FACE.body} size={size.text.detail} tone={color.muted} halo={halo}>{step.result.detail}</Type> : null}
79	              </div>
80	              <Type face={FACE.code} size={size.code.ref} leading={leading.code} tone={color.muted} halo={halo} style={{ position: 'absolute', left: pad, bottom: pad - space.sm }}>{fitRef(step.entryId, width)}</Type>
81	            </OnFrame>
82	          );
83	        })}
84	      </>
85	    );
86	  },
87	
88	  Glass: ({ scene }) => {
89	    const { m, steps, position } = useSteps(scene);
90	    const room = glassRoom(m.shot.lens, m.bottom);
91	    const ringed = glassRoom(m.shot.lens, m.bottom, loupe.rim + RING_RIM);
92	    const strip = stripOf(m.shot.unit, m.shot.half);
93	    const command = { max: size.code.command, min: size.code.command, leading: leading.code };
94	    const detail = size.text.detail * leading.text;
95	    return (
96	      <>
97	        {steps.map((step, i) => {
98	          // Each step is its own frame under the glass; only the one the lens is on, or is moving to, is in sight.
99	          if (Math.abs(i - position) >= 1) return null;
100	          const below = step.result.detail ? detail + space.xs : 0;
101	          const head = fitResult(step.result, linesRoom(ringed, COMMAND_LINES * command.max * command.leading + GAP, below));
102	          const typed = fitText(step.command, command, linesRoom(room, 0, GAP + heightOf(head) + below), emOf(FACE.code), { maxLines: COMMAND_LINES });
103	          const drawn = m.drawn(step.cue);
104	          const [w, h] = [widthOf(head, head.role.face), heightOf(head)];
105	          const halo = step.ok ? undefined : color.film.lit;
106	          return (
107	            <div key={i} style={{ position: 'absolute', left: i * strip.pitch * loupe.parallax, top: 0, width: 0, height: 0 }}>
108	              <GlassBlock at={room}>
109	                <Lines fitted={typed} face={FACE.code} leading={command.leading} align="center" tone={color.soft} halo={halo} style={{ position: 'relative', marginBottom: GAP }} />
110	                <div style={{ position: 'relative' }}>
111	                  {step.ok ? null : <Mark kind="cross" x={w / 2} y={h / 2} width={w * STRUCK.width} height={h * STRUCK.height} seed={i + 3} progress={drawn} />}
112	                  <Lines fitted={head} face={head.role.face} leading={head.role.type.leading} align="center" halo={halo} style={{ position: 'relative' }} />
113	                  {step.ok ? <Mark kind="ring" x={w / 2} y={h / 2} {...ringOf(head, head.role.face, head.role.type.leading, ringPad(head.size))} seed={i + 11} progress={drawn} /> : null}
114	                </div>
115	                {step.result.detail ? <Type face={FACE.body} size={size.text.detail} tone={color.soft} halo={halo} style={{ position: 'relative', height: detail, marginTop: space.xs }}>{step.result.detail}</Type> : null}
116	              </GlassBlock>
117	            </div>
118	          );
119	        })}
120	      </>
121	    );
122	  },
123	};
