// Shared by the composition and by the Node side of the renderer, so it imports nothing that needs a browser.
import type { LineTiming, Storyboard } from '@dailies/core';

export const COMPOSITION_ID = 'Reel';
export const WIDTH = 1920;
export const HEIGHT = 1080;
export const NARRATION_FILE = 'narration.wav';

/**
 * `audio` says whether `NARRATION_FILE` is in the public folder. Without it the reel is a captions cut.
 * `settled` is for review stills: every pencil mark and every step counts as already told, so the middle frame
 * of a scene shows all the scene will hold.
 */
export type ReelProps = { storyboard: Storyboard; timings: LineTiming[]; audio: boolean; settled?: boolean };
import React from 'react';
import { Composition, type CalculateMetadataFunction } from 'remotion';
import { FPS, buildTimeline } from '../timeline';
import { COMPOSITION_ID, HEIGHT, WIDTH, type ReelProps } from './config';
import { Reel } from './Reel';

// What the Studio shows before real props arrive; a render always passes its own.
const preview: ReelProps = {
  storyboard: {
    runId: 'preview',
    repo: 'owner/repository',
    targetSec: 75,
    facts: {},
    scenes: [
      { id: 'title', type: 'title', lines: [], repo: 'owner/repository', windowLabel: 'Last 7 days', sessionCount: 0, commitCount: 0 },
      { id: 'end', type: 'end', lines: [], repo: 'owner/repository', verified: 0, flagged: 0, unverified: 0 },
    ],
  },
  timings: [],
  audio: false,
};

const calculateMetadata: CalculateMetadataFunction<ReelProps> = ({ props }) => ({
  durationInFrames: buildTimeline(props.storyboard, props.timings, FPS).totalFrames,
});

export const Root: React.FC = () => (
  <Composition id={COMPOSITION_ID} component={Reel} width={WIDTH} height={HEIGHT} fps={FPS} defaultProps={preview} calculateMetadata={calculateMetadata} />
);
import { registerRoot } from 'remotion';
import { Root } from './Root';

registerRoot(Root);
// Film geometry: pure. A strip is laid out in "rest px": the scene as it sits when the lens has landed, with the
// origin at the point under the centre of the lens and x running along the film. Film.tsx draws from these boxes.
import { theme } from '../theme';

const { film } = theme;

export interface Strip {
  /** Screen px of one perforation pitch. */
  perf: number;
  /** Perforations per frame: eight for a full landscape frame, four for a portrait half-frame. */
  per: number;
  /** Screen px from one frame to the next. */
  pitch: number;
  height: number;
  frame: { top: number; width: number; height: number; radius: number };
}

/** The strip under a lens whose full-frame pitch is `unit` px. */
export function stripOf(unit: number, half: boolean): Strip {
  const per = half ? film.perforations / 2 : film.perforations;
  const perf = unit / film.perforations;
  const pitch = perf * per;
  return {
    perf,
    per,
    pitch,
    height: unit * film.height,
    frame: {
      top: unit * (film.frame.top - film.height / 2),
      width: pitch - unit * film.frame.gap,
      height: unit * film.frame.height,
